import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.HashMap;import java.util.Map;public class TestClass {private static final long[] memoArray = new long[1000001];private static final Map<Long, Long> memoMap = new HashMap<Long, Long>();public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line;while ((line = br.readLine()) != null && !line.trim().isEmpty()) {try {long n = Long.parseLong(line.trim());System.out.println(solve(n));} catch (NumberFormatException e) {break;}}}private static long solve(long n) {if (n < 1000000) {if (n < 12) return n;if (memoArray[(int) n] != 0) return memoArray[(int) n];long res = Math.max(n, solve(n / 2) + solve(n / 3) + solve(n / 4));memoArray[(int) n] = res;return res;} else {if (memoMap.containsKey(n)) return memoMap.get(n);long res = Math.max(n, solve(n / 2) + solve(n / 3) + solve(n / 4));memoMap.put(n, res);return res;}}}